/**
 * Bind a React element to the host's edit dialog. This helper has no registration or DOM side
 * effects: the element's React handler owns the click, and replacing it replaces the behavior.
 * Cloning DOM does not clone React event handlers; external layout adapters own their copies.
 *
 * A click anywhere inside opens the dialog, also when a descendant prevented its default (a link
 * kept from navigating the editor). A descendant that handles the click itself declines the dialog
 * with `event.stopPropagation()`.
 */
export function getDialogProps(props) {
  const dialog = props?.dialog;
  if (!dialog) return {};

  const markers = {
    'data-uhuu': '',
    ...(dialog.type ? { 'data-uhuu-type': dialog.type } : {}),
  };
  if (typeof window !== 'undefined' && window.$uhuu_renderer) return markers;

  return {
    ...markers,
    onClick(event) {
      if (typeof window === 'undefined' || window.$uhuu_renderer) return;
      event.stopPropagation();
      window.$uhuu?.editDialog?.(dialog);
    },
  };
}
